import { base64url } from "jose";

/**
 * Agent keys are ECDSA P-256 (ES256) everywhere: SDK hosts, phones (Secure Enclave / Keystore)
 * and WebAuthn. Keys are generated by the client; only the public JWK is registered.
 */

export interface P256PublicJwk {
  kty: "EC";
  crv: "P-256";
  x: string;
  y: string;
}

export interface AgentKeyPair {
  privateKey: CryptoKey;
  publicJwk: P256PublicJwk;
}

const ALGORITHM: EcKeyGenParams = { name: "ECDSA", namedCurve: "P-256" };

export async function generateAgentKeyPair(extractable = false): Promise<AgentKeyPair> {
  const pair = await crypto.subtle.generateKey(ALGORITHM, extractable, ["sign", "verify"]);
  const jwk = await crypto.subtle.exportKey("jwk", pair.publicKey);
  return { privateKey: pair.privateKey, publicJwk: toPublicJwk(jwk) };
}

export async function importPrivateJwk(jwk: JsonWebKey): Promise<CryptoKey> {
  return crypto.subtle.importKey("jwk", jwk, ALGORITHM, false, ["sign"]);
}

export function isP256PublicJwk(value: unknown): value is P256PublicJwk {
  if (typeof value !== "object" || value === null) return false;
  const jwk = value as Record<string, unknown>;
  if (jwk.kty !== "EC" || jwk.crv !== "P-256") return false;
  if (typeof jwk.x !== "string" || typeof jwk.y !== "string") return false;
  try {
    return base64url.decode(jwk.x).length === 32 && base64url.decode(jwk.y).length === 32;
  } catch {
    return false;
  }
}

/** Strip a JWK down to its public members, rejecting anything that isn't a P-256 public key. */
export function toPublicJwk(jwk: JsonWebKey): P256PublicJwk {
  const pub = { kty: jwk.kty, crv: jwk.crv, x: jwk.x, y: jwk.y };
  if (!isP256PublicJwk(pub)) throw new TypeError("expected a P-256 public JWK");
  return pub;
}

/** Uncompressed SEC1 point (0x04 || x || y) for fast verification with @noble/curves. */
export function publicJwkToRaw(jwk: P256PublicJwk): Uint8Array {
  const x = base64url.decode(jwk.x);
  const y = base64url.decode(jwk.y);
  const raw = new Uint8Array(65);
  raw[0] = 0x04;
  raw.set(x, 1);
  raw.set(y, 33);
  return raw;
}
